function canonical(v){if(v===null)return 'null';if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v);}
async function digest(v){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(v)));return Array.from(new Uint8Array(b)).map(x=>x.toString(16).padStart(2,'0')).join('');}
async function principal(db){const q=await db.auth.getUser();if(q.error||q.data?.user?.id!==EXPECTED)throw Error('Account amministratore non verificato');const m=await db.from('agenda_members').select('enabled').eq('user_id',EXPECTED).eq('enabled',true).maybeSingle();if(m.error||m.data?.enabled!==true)throw Error('Accesso Agenda non abilitato');return EXPECTED;}
async function one(db,table,id,columns){if(!UUID.test(id||''))throw Error('Identificativo non valido');const q=await db.from(table).select(columns).eq('id',id).maybeSingle();if(q.error||q.data?.id!==id)throw Error('Fonte '+table+' non verificata');return q.data;}
