 if(tel&&cell&&tel!==cell)v.client_phone=tel+' -- '+cell;else if(tel||cell)v.client_phone=tel||cell;
 if(!e.timezone||!e.starts_at||!Number.isInteger(e.version)||e.version<1)throw Error('Data/fuso/versione evento non verificati');
 // La data evento non attesta la data della dichiarazione: viene mostrata come riferimento, non compilata.
 v.visit_date='';
 put('property_ref',p.codice);put('property_city',p.comune);put('property_street',p.indirizzo);put('property_tipo',p.tipologia);put('property_operazione',p.tipo_operazione);
 // Optional numeric columns: fail-closed like the Python transformers (integral only, no invented decimal format).
 const integral=(value,label)=>{if(value===null||value===undefined||String(value).trim()==='')return null;if(typeof value==='boolean')throw Error(label+': booleano non numerico');if(typeof value==='number'){if(Number.isInteger(value))return String(value);throw Error(label+': numero non integrale, formato decimale non verificato');}const t=String(value).trim();if(!/^\d+$/.test(t))throw Error(label+': formato non verificato');return t;};
